import { lstat, readFile } from "node:fs/promises";
import { join } from "node:path";

import orgAgents from "../../../../../.holocron/org.md";
import type { GeneratedRepoFile, RepoFilesInput, SkippedRepoFile } from "./repo-files.type.js";

// The marker text is matched verbatim in every other repo's AGENTS.md; rewording it appends a second block there.
export const ORG_BLOCK_BEGIN =
	"<!-- BEGIN holocron org agent instructions (generated by `holocron repo sync` from theholocron/holocron .agents/org.md; do not edit) -->";
export const ORG_BLOCK_END = "<!-- END holocron org agent instructions -->";

/** The generated block: the org agent instructions between two markers. */
export function orgAgentsBlock(): string {
	return `${ORG_BLOCK_BEGIN}\n\n${orgAgents.trim()}\n\n${ORG_BLOCK_END}\n`;
}

/**
 * `text` with the generated block set to the current org instructions: replaced in place when the markers are there,
 * appended otherwise. A file that imports `@.holocron/org.md` (holocron itself) already has them and is left alone.
 */
export function withOrgBlock(text: string): string {
	if (/^@\.holocron\/org\.md\s*$/m.test(text)) return text;
	const start = text.indexOf(ORG_BLOCK_BEGIN);
	const end = text.indexOf(ORG_BLOCK_END);
	if (start !== -1 && end > start) {
		return `${text.slice(0, start)}${orgAgentsBlock()}${text.slice(end + ORG_BLOCK_END.length).replace(/^\n/, "")}`;
	}
	return `${text.replace(/\n*$/, "\n\n")}${orgAgentsBlock()}`;
}

/**
 * The org agent instructions as a generated block in the repo's `AGENTS.md` (or `CLAUDE.md` when that is the only
 * file, a symlink to `AGENTS.md` being the same file). The rest of the file is the repo's own and is kept. A repo with
 * neither file gets none: this does not create the contract, only keeps the shared part of it current.
 */
export async function generateAgentFiles(input: RepoFilesInput): Promise<(GeneratedRepoFile | SkippedRepoFile)[]> {
	const path = await agentsFile(input.repoRoot);
	const step = `write ${path ?? "AGENTS.md"}`;
	if (path === null) return [{ kind: "skip", step, syncStep: step, message: "no AGENTS.md or CLAUDE.md" }];
	const existing = await readFile(join(input.repoRoot, path), "utf8");
	const content = withOrgBlock(existing);
	if (content === existing && !existing.includes(ORG_BLOCK_BEGIN)) {
		return [{ kind: "skip", step, syncStep: step, message: "imports .holocron/org.md" }];
	}
	return [{ kind: "file", path, content, step, syncStep: step, note: "org agent instructions block" }];
}

async function agentsFile(root: string): Promise<string | null> {
	for (const name of ["AGENTS.md", "CLAUDE.md"]) {
		const stat = await lstat(join(root, name)).catch(() => null);
		if (stat?.isFile()) return name;
	}
	return null;
}
